import { createContext, useContext, useEffect, useState } from "react";

const OrderContext = createContext();

export function OrderProvider({ children }) {
  const [orders, setOrders] = useState([]);

  // ✅ FETCH ORDERS FROM DJANGO BACKEND
  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/orders/")
      .then(res => res.json())
      .then(data => setOrders(data))
      .catch(err => console.error("Order fetch error", err));
  }, []);

  // ✅ PLACE ORDER (POST TO BACKEND)
  function placeOrder(order) {
    fetch("http://127.0.0.1:8000/api/orders/", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(order),
    })
      .then(res => res.json())
      .then(newOrder => setOrders(prev => [newOrder, ...prev]));
  }

  // ✅ UPDATE ORDER STATUS (ADMIN)
  function updateOrderStatus(id, status) {
    fetch(`http://127.0.0.1:8000/api/orders/${id}/`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status }),
    })
      .then(res => res.json())
      .then(updated =>
        setOrders(prev =>
          prev.map(o => (o.id === updated.id ? updated : o))
        )
      );
  }

  return (
    <OrderContext.Provider value={{ orders, placeOrder, updateOrderStatus }}>
      {children}
    </OrderContext.Provider>
  );
}

export function useOrders() {
  return useContext(OrderContext);
}
